"""Find stretches of opening hours that nobody covers."""

from typing import List

from hourglass.parsing import format_span
from hourglass.models import Span
from hourglass.merging import merge_spans

def find_gaps(worked: List[Span], hours: Span) -> List[str]:
    """One label for each stretch of hours nobody covers."""
    spans = merge_spans(worked)
    _check_within(spans, hours)
    return [_gap_label(stretch) for stretch in _gaps(spans, hours)]

def _check_within(spans: List[Span], hours: Span) -> None:
    """Raise if a span falls outside the hours."""
    for span in spans:
        if span.start < hours.start or span.end > hours.end:
            shown = format_span(span)
            limit = format_span(hours)
            raise ValueError(f"{shown} is outside {limit}")

def _gaps(spans: List[Span], hours: Span) -> List[Span]:
    """Stretches of hours left open by the spans."""
    found = []
    for start, stop in _edge_pairs(spans, hours):
        if start < stop:
            found.append(Span(start, stop))
    return found

def _edge_pairs(spans: List[Span], hours: Span) -> list:
    """Each stretch from a span end to the next start."""
    starts = [hours.start] + [span.end for span in spans]
    stops = [span.start for span in spans] + [hours.end]
    return list(zip(starts, stops))

def _gap_label(stretch: Span) -> str:
    return f"gap {format_span(stretch)} ({stretch.minutes} min)"
